'use client';

import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDownLeft, ArrowRight, ArrowUpRight, Bookmark, Building2, CalendarDays, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleCheck, Clock3, Compass, Copy, Database, Download, ExternalLink, FileText, Globe2, LayoutDashboard, ListFilter, LoaderCircle, LogOut, Mail, MapPin, Menu, MessageCircle, Phone, Plus, Radar, Search, Send, Settings2, ShieldCheck, Sparkles, TrendingUp, Wallet, X } from 'lucide-react';
import Landing from './landing';
import AuthScreen, { type AuthMode } from './auth-screen';
import { PROVINCES, SERVICES, STAGES, type Analysis, type Business, type Dashboard, type Job, type Lead, type LedgerEntry, type Profile, type SearchFilters, type SearchResult, type User } from '@/lib/contracts';

type View='dashboard'|'search'|'business'|'outreach'|'leads'|'account'|'admin';
type AdminData={workspaces:{id:string;name:string;email:string}[];jobs:{id:string;status:string;attempts:number;error:string|null}[];requests:PrivacyRequest[];corrections:{id:string;note:string;status:string}[]};
type PrivacyRequest={id:string;type:string;status:string;created_at?:string};
const categories=['Restauração','Serviços profissionais','Retalho','Hotelaria'];
const money=(minor:number)=>new Intl.NumberFormat('pt-MZ',{maximumFractionDigits:0}).format(minor/100)+' MT';
const date=(value:string)=>new Intl.DateTimeFormat('pt-MZ',{day:'numeric',month:'short',timeZone:'Africa/Maputo'}).format(new Date(value));
const cls=(...values:(string|false|undefined)[])=>values.filter(Boolean).join(' ');
async function api<T>(path:string,options:RequestInit={}):Promise<T>{const response=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível concluir o pedido.');return data;}
const post=<T,>(path:string,data:unknown={})=>api<T>(path,{method:'POST',body:JSON.stringify(data)});
function IconButton({label,onClick,children}:{label:string;onClick:()=>void;children:ReactNode}){return <button className="icon-button" aria-label={label} title={label} onClick={onClick}>{children}</button>;}
function Pill({children,tone='blue'}:{children:ReactNode;tone?:string}){return <span className={'pill '+tone}>{children}</span>;}
function Empty({icon=<Compass size={28}/>,title,description,children}:{icon?:ReactNode;title:string;description:string;children?:ReactNode}){return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{description}</p>{children}</div>;}
function Brand({light=false}:{light?:boolean}){return <div className={cls('brand',light&&'light')}><span className="brand-mark"><Radar size={24} strokeWidth={2.4}/></span><div>prospecta<span>INTELIGÊNCIA COMERCIAL · MZ</span></div></div>;}

export default function Prospecta({initialAuth=null}:{initialAuth?:AuthMode|null}={}){
 const [user,setUser]=useState<User|null>(null),[loading,setLoading]=useState(true),[mode,setMode]=useState<'demo'|'live'>('demo');
 const [view,setView]=useState<View>('dashboard'),[auth,setAuth]=useState<AuthMode|null>(initialAuth),[busy,setBusy]=useState(false);
 const [mobileMenu,setMobileMenu]=useState(false),[toast,setToast]=useState<{message:string;error?:boolean}|null>(null);
 const [dashboard,setDashboard]=useState<Dashboard|null>(null),[searchResult,setSearchResult]=useState<SearchResult|null>(null);
 const [filters,setFilters]=useState<SearchFilters>({niche:'',cities:'',phone:'all',website:'all',instagram:'all',province:'',locality:'',category:'',service:SERVICES[0],budget:11});
 const [pastSearches,setPastSearches]=useState<SearchResult[]>([]);
 const [business,setBusiness]=useState<Business|null>(null),[analysis,setAnalysis]=useState<Analysis|null>(null),[leads,setLeads]=useState<Lead[]>([]),[selectedLead,setSelectedLead]=useState<Lead|null>(null);
 const [draft,setDraft]=useState(''),[tone,setTone]=useState('Profissional'),[service,setService]=useState<string>(SERVICES[0]),[job,setJob]=useState<Job|null>(null);
 const [usage,setUsage]=useState<LedgerEntry[]>([]),[requests,setRequests]=useState<PrivacyRequest[]>([]),[outbox,setOutbox]=useState<{id:string;kind:string;link:string}[]>([]),[admin,setAdmin]=useState<AdminData|null>(null);
 const [stageFilter,setStageFilter]=useState(''),[leadSearch,setLeadSearch]=useState(''),[profile,setProfile]=useState<Profile|null>(null);
 const activeBusiness=useRef<string|null>(null);useEffect(()=>{activeBusiness.current=business?.id||null;},[business?.id]);
 const resetWorkspace=useCallback(()=>{setDashboard(null);setSearchResult(null);setPastSearches([]);setBusiness(null);setAnalysis(null);setLeads([]);setSelectedLead(null);setDraft('');setJob(null);setUsage([]);setRequests([]);setOutbox([]);setAdmin(null);setProfile(null);},[]);
 const notify=useCallback((message:string,error=false)=>setToast({message,error}),[]);
 const loadPastSearches=useCallback(async()=>{try{const res=await api<{searches:SearchResult[]}>('searches');setPastSearches(res.searches||[]);}catch{}},[]);
 const refreshUser=useCallback(async()=>{const result=await api<{user:User|null;mode:'demo'|'live'}>('me');setUser(result.user);setMode(result.mode);return result.user;},[]);
 const navigate=useCallback((next:View,b?:Business)=>{setView(next);setMobileMenu(false);if(next==='leads')setSelectedLead(null);if(b)setBusiness(b);const url=new URL(window.location.href);url.pathname='/';url.searchParams.delete('auth_error');url.searchParams.set('view',next);if(b)url.searchParams.set('business',b.id);else if(!['business','outreach'].includes(next))url.searchParams.delete('business');window.history.replaceState({},'',url);window.scrollTo({top:0,behavior:'instant'});},[]);
 const loadBusiness=useCallback(async(businessId:string,next:View='business')=>{const result=await api<{business:Business;analysis:Analysis|null;lead:Lead|null}>('businesses/'+businessId);setBusiness(result.business);setAnalysis(result.analysis);setDraft(result.analysis?.draftMessage||'');setSelectedLead(result.lead);navigate(next,result.business);},[navigate]);
 useEffect(()=>{let active=true;api<{user:User|null;mode:'demo'|'live'}>('me').then(result=>{if(!active)return;setUser(result.user);setMode(result.mode);const query=new URLSearchParams(window.location.search);if(result.user&&initialAuth&&!query.get('reset')){setAuth(null);navigate('dashboard');}if(query.get('auth')==='recover')setAuth('recover');const oauthError=query.get('auth_error');if(oauthError)notify(oauthError==='google_cancelled'?'O acesso com Google foi cancelado. Pode tentar novamente.':oauthError==='google_terms'?'Para continuar com Google, crie a conta e aceite os termos.':'Não foi possível concluir o acesso com Google. Tente novamente ou entre com e-mail.',true);const initial=query.get('view') as View|null;if(initial&&['dashboard','search','leads','account','admin','business','outreach'].includes(initial))setView(initial);if(result.user&&query.get('business'))loadBusiness(query.get('business')!,initial==='outreach'?'outreach':'business').catch(e=>notify(e.message,true));if(query.get('reset')||new URLSearchParams(window.location.hash.slice(1)).get('type')==='recovery')setAuth('reset');if(query.get('confirm'))post('auth/confirm',{token:query.get('confirm')}).then(()=>notify('E-mail confirmado.')).catch(e=>notify(e.message,true));}).catch(e=>notify(e.message,true)).finally(()=>setLoading(false));return()=>{active=false;};},[loadBusiness,notify,initialAuth,navigate]);
 useEffect(()=>{const sync=()=>{const path=window.location.pathname;if(path==='/cadastro')setAuth('register');else if(path==='/login')setAuth(new URLSearchParams(window.location.search).get('auth')==='recover'?'recover':'login');else setAuth(null);};window.addEventListener('popstate',sync);return()=>window.removeEventListener('popstate',sync);},[]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(null),6500);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{
  if(!(view==='leads'&&selectedLead))return;
  const previous=document.activeElement as HTMLElement|null;
  const frame=requestAnimationFrame(()=>{const dialog=document.querySelector<HTMLElement>('[role="dialog"]');dialog?.querySelector<HTMLElement>('input,button,select,textarea,a[href]')?.focus();});
  const keydown=(event:KeyboardEvent)=>{
   if(event.key==='Escape'){setSelectedLead(null);}
   if(event.key==='Tab'){const dialog=document.querySelector<HTMLElement>('[role="dialog"]');const items=Array.from(dialog?.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,textarea,a[href]')||[]);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  };
  document.addEventListener('keydown',keydown);return()=>{cancelAnimationFrame(frame);document.removeEventListener('keydown',keydown);previous?.focus();};
 },[view,selectedLead]);
 useEffect(()=>{if(!user)return;let active=true;async function load(){
  if(view==='dashboard'){const result=await api<Dashboard>('dashboard');if(active)setDashboard(result);}
  if(view==='search'){const res=await api<{searches:SearchResult[]}>('searches');if(active)setPastSearches(res.searches||[]);}
  if(view==='leads'){const result=await api<{leads:Lead[]}>('leads');if(active)setLeads(result.leads);}
  if(view==='account'){const [u,p,o]=await Promise.all([api<{entries:LedgerEntry[]}>('usage'),api<{requests:PrivacyRequest[]}>('privacy'),api<{messages:typeof outbox}>('outbox')]);if(active){setUsage(u.entries);setRequests(p.requests);setOutbox(o.messages);setProfile(user!.profile);}}
  if(view==='admin'){const result=await api<AdminData>('admin');if(active)setAdmin(result);}
 }load().catch(e=>notify(e.message,true));return()=>{active=false;};},[view,user,notify]);

 function openAuth(next:AuthMode|null){setAuth(next);const url=new URL(window.location.href);url.pathname=next==='register'?'/cadastro':next?'/login':'/';url.search='';url.hash='';if(next==='recover')url.searchParams.set('auth','recover');window.history.pushState({},'',url);window.scrollTo({top:0,behavior:'instant'});}
 async function startGoogle(consent:{acceptedTerms:boolean;marketing:boolean}){await run(async()=>{const result=await post<{redirectUrl:string}>('auth/google',{intent:auth==='register'?'register':'login',...consent});window.location.assign(result.redirectUrl);});}
 async function run(operation:()=>Promise<void>){setBusy(true);try{await operation();}catch(error){notify(error instanceof Error?error.message:'Ocorreu um erro.',true);}finally{setBusy(false);}}
 async function enterDemo(){await run(async()=>{const result=await post<{user:User}>('auth/demo');resetWorkspace();setUser(result.user);setService(result.user.profile.service);navigate('search');notify('O seu espaço de demonstração está pronto. Todos os negócios são fictícios.');});}
 async function authenticate(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);await run(async()=>{
  if(auth==='recover'){const result=await post<{message:string}>('auth/recover',{email:form.get('email')});notify(result.message);openAuth('login');return;}
  if(auth==='reset'){const recovery=new URLSearchParams(window.location.hash.slice(1));await post('auth/reset',{token:new URLSearchParams(window.location.search).get('reset'),accessToken:recovery.get('access_token'),refreshToken:recovery.get('refresh_token'),password:form.get('password')});window.history.replaceState({},'',window.location.pathname);resetWorkspace();setUser(null);openAuth('login');notify('Palavra-passe actualizada. Entre novamente.');return;}
  const result=await post<{user?:User;confirmationRequired?:boolean;message?:string}>('auth/'+auth,{name:form.get('name'),email:form.get('email'),password:form.get('password'),phone:form.get('phone')||'',acceptedTerms:form.get('terms')==='on',consent:form.get('marketing')==='on'});
  if(result.confirmationRequired){notify(result.message||'Confirme o seu e-mail.');openAuth('login');return;}if(result.user){resetWorkspace();setUser(result.user);setProfile(result.user.profile);setAuth(null);navigate('dashboard');}
 });}
 async function saveProfile(event:FormEvent<HTMLFormElement>,onboarded=true){event.preventDefault();const form=new FormData(event.currentTarget);await run(async()=>{const result=await api<{user:User}>('profile',{method:'PUT',body:JSON.stringify({name:String(form.get('name')||user?.name),service:String(form.get('service')),pitch:String(form.get('pitch')),province:String(form.get('province')),phone:String(form.get('phone')||''),nationwide:form.get('nationwide')==='on',onboarded})});setUser(result.user);setProfile(result.user.profile);setService(result.user.profile.service);notify('Perfil guardado.');});}
 async function doSearch(page?:number,customFilters?:SearchFilters){await run(async()=>{
  const searchParams=customFilters||filters;
  let result=page&&searchResult?await api<SearchResult>(`searches/${searchResult.id}?page=${page}`):await post<SearchResult>('searches',searchParams);setSearchResult(result);
  for(let i=0;['queued','running'].includes(result.status)&&i<80;i++){await new Promise(r=>setTimeout(r,650));result=await api<SearchResult>('searches/'+result.id);setSearchResult(result);}
  if(['queued','running'].includes(result.status))notify('A pesquisa continua em curso. Verifique se o processador de tarefas está iniciado.',true);
  else loadPastSearches();
 });}
 async function resumeSearch(item:SearchResult){
  setFilters(item.filters);
  await run(async()=>{
   try{
    const full=await api<SearchResult>(`searches/${item.id}`);
    setSearchResult(full);
   }catch{
    await doSearch(undefined,item.filters);
   }
  });
 }
 async function saveBusiness(b:Business){await run(async()=>{const result=await post<{lead:Lead}>('leads',{businessId:b.id});setSelectedLead(result.lead);if(business?.id===b.id)setBusiness({...b,saved:true});setSearchResult(previous=>previous?{...previous,results:previous.results.map(item=>item.id===b.id?{...item,saved:true}:item)}:previous);notify('Empresa guardada nas suas oportunidades.');});}
 async function generate(fresh=false){if(!business)return;await run(async()=>{
  let result=await api<Job>('analyses',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({businessId:business.id,tone,service,fresh})});setJob(result);
  for(let i=0;['queued','running'].includes(result.status)&&i<90;i++){await new Promise(r=>setTimeout(r,650));result=await api<Job>('jobs/'+result.id);setJob(result);}
  if(result.status==='succeeded'&&result.result){if(activeBusiness.current===result.result.businessId){setAnalysis(result.result);setDraft(result.result.draftMessage);}await refreshUser();notify('Análise e mensagem preparadas.');}
  else if(result.status==='failed'){await refreshUser();throw new Error(result.error||'A análise falhou; a reserva foi libertada.');}
  else if(result.status==='cancelled'){await refreshUser();notify('Análise cancelada.');}
  else notify('A tarefa continua em curso. Pode consultar o resultado mais tarde.',true);
 });}
 async function saveDraft(){if(!analysis)return;await run(async()=>{const result=await api<{analysis:Analysis}>('drafts/'+analysis.id,{method:'PATCH',body:JSON.stringify({body:draft})});setAnalysis(result.analysis);notify('Mensagem guardada.');});}
 async function copyDraft(){try{await navigator.clipboard.writeText(draft);notify('Mensagem copiada. Reveja antes de enviar.');}catch{notify('Não foi possível copiar. Seleccione o texto e copie manualmente.',true);}}
 async function openLead(lead:Lead){setSelectedLead(lead);}
 async function updateLead(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedLead)return;const form=new FormData(event.currentTarget);await run(async()=>{const amount=String(form.get('amount')||'');const due=String(form.get('due')||'');const result=await api<{lead:Lead}>('leads/'+selectedLead.id,{method:'PATCH',body:JSON.stringify({stage:form.get('stage'),note:form.get('note'),nextAction:form.get('nextAction'),nextActionAt:due?new Date(due).toISOString():null,amountMinor:amount?Math.round(Number(amount)*100):null})});setSelectedLead(result.lead);setLeads(previous=>previous.map(l=>l.id===result.lead.id?result.lead:l));notify('Oportunidade actualizada.');});}
 async function requestPrivacy(type:'export'|'delete'){if(type==='delete'&&!window.confirm('Pretende pedir a eliminação da sua conta e dados privados? O pedido será revisto pela administração.'))return;await run(async()=>{const result=await post<{request:PrivacyRequest}>('privacy',{type});setRequests(previous=>[result.request,...previous]);notify(type==='export'?'Exportação pronta para descarregar.':'Pedido de eliminação registado.');});}
 const nav=[{view:'dashboard' as View,label:'Visão geral',icon:LayoutDashboard},{view:'search' as View,label:'Encontrar empresas',icon:Compass},{view:'leads' as View,label:'Minhas oportunidades',icon:Bookmark},{view:'account' as View,label:'Conta e utilização',icon:Wallet}];

 if(loading)return <div className="boot"><Brand/><LoaderCircle className="spin"/><p>A preparar o seu espaço…</p></div>;
 const toastUi=toast&&<div role={toast.error?'alert':'status'} className={cls('toast',toast.error&&'error')}>{toast.error?<ShieldCheck size={19}/>:<CircleCheck size={19}/>}<span>{toast.message}</span><IconButton label="Fechar mensagem" onClick={()=>setToast(null)}><X size={16}/></IconButton></div>;

 if(!user || auth==='reset')return <div className="public-page">{toastUi}{auth?<AuthScreen key={auth} kind={auth} mode={mode} busy={busy} onSubmit={authenticate} onSwitch={openAuth} onHome={()=>openAuth(null)} onGoogle={startGoogle}/>:<Landing mode={mode} busy={busy} onRegister={()=>openAuth('register')} onLogin={()=>openAuth('login')} onDemo={enterDemo}/>}</div>;

 return <div className="app">{toastUi}<a className="skip-link" href="#main">Saltar para o conteúdo</a>{mobileMenu&&<div className="sidebar-backdrop" onClick={()=>setMobileMenu(false)}/>}
 <aside className={cls('sidebar',mobileMenu&&'open')}><Brand/><div className="workspace-label"><span className="workspace-avatar">P</span><div>O meu espaço<span>Piloto Prospecta</span></div><ChevronDown size={14}/></div><span className="nav-label">ESPAÇO DE TRABALHO</span><nav aria-label="Navegação principal">{nav.map(item=><button key={item.view} className={cls('nav-item',view===item.view&&'active')} onClick={()=>navigate(item.view)}><item.icon size={19}/><span>{item.label}</span>{item.view==='search'&&<span className="nav-new">NOVO</span>}</button>)}{user.role==='admin'&&<button className={cls('nav-item',view==='admin'&&'active')} onClick={()=>navigate('admin')}><ShieldCheck size={19}/><span>Administração</span></button>}</nav><div className="sidebar-bottom"><div className="credit-card"><div className="row"><span className="micro-label">O SEU PRÓXIMO PASSO</span><Sparkles size={16}/></div><h3>{user.credits.available} <small>créditos disponíveis</small></h3><div className="credit-meter"><span style={{width:`${Math.min(100,user.credits.available/20*100)}%`}}/></div><p>Uma análise. Uma nova possibilidade.</p><button onClick={()=>navigate('account')}>Ver utilização <ArrowRight size={14}/></button></div><button className="user-card" onClick={()=>navigate('account')}><span className="avatar">{user.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><span><strong>{user.name}</strong><small>{user.profile.province||'Moçambique'}</small></span><Settings2 size={17}/></button><button className="logout" disabled={busy} onClick={()=>run(async()=>{await post('auth/logout');resetWorkspace();setUser(null);setAuth(null);})}><LogOut size={15}/> Terminar sessão</button></div></aside>
 <div className="app-main"><header className="topbar"><div className="topbar-left"><IconButton label="Abrir menu" onClick={()=>setMobileMenu(!mobileMenu)}><Menu size={20}/></IconButton><span className="breadcrumb">O meu espaço <ChevronRight size={13}/> <b>{view==='business'?'Ficha da empresa':view==='outreach'?'Preparar abordagem':view==='admin'?'Administração':nav.find(n=>n.view===view)?.label}</b></span></div><div className="topbar-right"><span className="country"><span className="country-dot"/> Moçambique</span><button className="balance" onClick={()=>navigate('account')}><Sparkles size={14}/>{user.credits.available} créditos</button><span className="avatar small">{user.name.slice(0,1)}</span></div></header>
 <main id="main" className="workspace"><div className="mode-banner"><span><span className="live-dot"/>{mode==='demo'?'ESPAÇO DE DEMONSTRAÇÃO':'AMBIENTE REAL'}</span><p>{mode==='demo'?'Empresas fictícias e análise simulada. As suas alterações ficam guardadas neste servidor local.':'Consulte sempre as fontes e confirme as necessidades com a empresa.'}</p><ShieldCheck size={16}/></div>
 {!user.profile.onboarded&&<section className="panel onboarding"><div><span className="eyebrow">BEM-VINDO À PROSPECTA</span><h2>Primeiro, diga-nos o que faz.</h2><p className="muted">A sua apresentação ajuda a preparar abordagens com a sua voz.</p></div><ProfileForm user={user} profile={profile||user.profile} busy={busy} onSubmit={saveProfile}/></section>}
 {user.profile.onboarded&&view==='dashboard'&&<><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> UM NOVO DIA, NOVAS POSSIBILIDADES</div><h1>Bom trabalho, {user.name.split(' ')[0]} <span className="wave">✳</span></h1><p>Uma visão clara para dar o próximo passo.</p></div><button className="button" onClick={()=>navigate('search')}><Plus size={18}/> Encontrar empresas</button></div><div className="stat-grid">{[{label:'Oportunidades guardadas',value:dashboard?.leads??0,icon:Bookmark,detail:'Empresas no seu acompanhamento',color:'blue'},{label:'Seguimentos pendentes',value:dashboard?.due??0,icon:CalendarDays,detail:'Até ao final de hoje',color:'amber'},{label:'Créditos disponíveis',value:user.credits.available,icon:Sparkles,detail:'Para preparar a próxima abordagem',color:'purple'},{label:'Propostas em negociação',value:money(dashboard?.proposalsMinor??0),icon:TrendingUp,detail:'Soma das oportunidades em Proposta',color:'green'}].map(s=><article className="stat-card" key={s.label}><div className="row"><span>{s.label}</span><span className={'stat-icon '+s.color}><s.icon size={18}/></span></div><strong>{s.value}</strong><p>{s.detail}</p></article>)}</div><div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>O caminho de cada oportunidade</h2><p>Do primeiro contacto à próxima conquista.</p></div><Pill>{dashboard?.leads??0} no total</Pill></div><div className="pipeline-summary">{STAGES.map((stage,i)=><button key={stage} onClick={()=>{setStageFilter(stage);navigate('leads');}}><span className={'stage-dot stage-'+i}/><span>{stage}</span><b>{dashboard?.stages.find(s=>s.stage===stage)?.count??0}</b><div className="pipeline-bar"><span style={{width:`${Math.max(3,(dashboard?.stages[i]?.count||0)/Math.max(1,dashboard?.leads||1)*100)}%`}}/></div></button>)}</div><div className="panel-footer"><span><CircleCheck size={14}/> Etapas actualizadas por si</span><button className="text-button" onClick={()=>navigate('leads')}>Ver oportunidades <ArrowRight size={14}/></button></div></section><section className="discovery-callout"><div className="callout-top"><span className="outlined-icon"><Compass size={25}/></span><span>O SEU ALCANCE É NACIONAL</span></div><h2>Novos negócios.<br/>Em novos lugares.</h2><p>Explore empresas do Norte, Centro e Sul. Comece pela zona onde o seu trabalho pode fazer a diferença.</p><button onClick={()=>navigate('search')}>Explorar Moçambique <ArrowUpRight size={19}/></button><div className="callout-orbit"/></section></div><div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>Os seus próximos passos</h2><p>Pequenas acções mantêm as conversas vivas.</p></div><CalendarDays size={19}/></div>{dashboard?.tasks.length?dashboard.tasks.map(l=><button className="task-row" key={l.id} onClick={()=>{setSelectedLead(l);navigate('leads');}}><span className="soft-icon"><CalendarDays size={20}/></span><span><b>{l.business.name}</b><small>{l.nextAction||'Retomar a conversa'} · {l.nextActionAt&&date(l.nextActionAt)}</small></span><ArrowUpRight size={17}/></button>):<Empty icon={<CalendarDays size={26}/>} title="Agenda livre, possibilidades abertas." description="Agende um seguimento numa oportunidade e encontre aqui o seu próximo passo."/>}</section><section className="panel"><div className="panel-heading"><div><h2>Actividade recente</h2><p>O que aconteceu no seu espaço.</p></div><Clock3 size={18}/></div>{dashboard?.recent.length?<div className="activity-list">{dashboard.recent.slice(0,5).map(a=><div key={a.id}><span className="activity-dot"/><div><p>{a.note}</p><small>{date(a.createdAt)}</small></div></div>)}</div>:<Empty icon={<ArrowUpRight size={26}/>} title="A sua história começa agora." description="As empresas guardadas e as alterações vão aparecer aqui."/>}</section></div></>}
 {user.profile.onboarded&&view==='search'&&<><div className="page-heading"><div><div className="eyebrow"><Compass size={14}/> RADAR DE OPORTUNIDADES</div><h1>O próximo cliente pode estar aqui.</h1><p>Defina o nicho e as cidades. Localize negócios reais e identifique pontos de contacto.</p></div><span className="national-badge"><Globe2 size={18}/> Cobertura nacional</span></div><section className="panel search-panel radar-search-panel"><form onSubmit={e=>{e.preventDefault();doSearch();}}><div className="filter-heading"><span><Radar size={17}/> Nova busca</span><button type="button" className="text-button muted" onClick={()=>setFilters({niche:'',cities:'',phone:'all',website:'all',instagram:'all',province:'',locality:'',category:'',service:user.profile.service,budget:11})}>Limpar campos</button></div><div className="radar-row-1"><label className="field-group"><span className="field-label">Nicho</span><input value={filters.niche||''} onChange={e=>setFilters({...filters,niche:e.target.value})} placeholder="Ex.: Clínicas odontológicas, Restaurantes, Salões"/></label><label className="field-group"><span className="field-label">Cidades (até 5, separadas por vírgula)</span><input value={filters.cities||''} onChange={e=>setFilters({...filters,cities:e.target.value})} placeholder="Maputo, Matola, Beira"/></label></div><div className="radar-row-2"><label className="field-group"><span className="field-label">Telefone</span><select value={filters.phone||'all'} onChange={e=>setFilters({...filters,phone:e.target.value})}><option value="all">Todos</option><option value="with_phone">Com telefone/WhatsApp</option></select></label><label className="field-group"><span className="field-label">Website</span><select value={filters.website||'all'} onChange={e=>setFilters({...filters,website:e.target.value})}><option value="all">Todos</option><option value="without_website">Sem website</option><option value="with_website">Com website</option></select></label><label className="field-group"><span className="field-label">Instagram</span><select value={filters.instagram||'all'} onChange={e=>setFilters({...filters,instagram:e.target.value})}><option value="all">Todos</option><option value="with_instagram">Com Instagram</option><option value="without_instagram">Sem Instagram</option></select></label><label className="field-group"><span className="field-label">O serviço que oferece</span><select value={filters.service||SERVICES[0]} onChange={e=>setFilters({...filters,service:e.target.value})}>{SERVICES.map(s=><option key={s}>{s}</option>)}</select></label><div className="radar-action-col"><button className="button radar-submit-button" disabled={busy}>{busy?<LoaderCircle className="spin" size={17}/>:<Search size={17}/>}Buscar negócios</button></div></div></form>{pastSearches.length>0&&<div className="radar-my-searches"><div className="radar-my-searches-header"><span className="radar-my-searches-title"><Clock3 size={15}/> Minhas buscas <small>(Retome buscas anteriores)</small></span></div><div className="radar-search-pills">{pastSearches.map(item=>{const nichePart=item.filters.niche||item.filters.category||'Qualquer nicho';const locPart=item.filters.cities||item.filters.locality||item.filters.province||'Todo Moçambique';const statusPart=item.status==='succeeded'?'Concluída':item.status==='running'?'Em curso':item.status==='partial'?'Parcial':'Incompleta';const isSelected=searchResult?.id===item.id;return <button key={item.id} type="button" className={cls('radar-search-pill',isSelected&&'active')} onClick={()=>resumeSearch(item)}><span className="pill-query">{nichePart} — {locPart}</span><span className="pill-dot">·</span><span className="pill-status">{statusPart}</span></button>;})}</div></div>}</section>
 {searchResult?<><div className="results-heading"><div><h2>{searchResult.total} empresas encontradas <Pill>{searchResult.mode==='demo'?'Demonstração':'Fonte autorizada'}</Pill></h2><p>{[searchResult.filters.niche,searchResult.filters.cities].filter(Boolean).join(' — ')||[searchResult.filters.province,searchResult.filters.locality].filter(Boolean).join(' · ')||'Todo Moçambique'} · Página {searchResult.page} de {searchResult.pages}</p></div><span className="muted micro">{searchResult.status==='succeeded'?'Consulta concluída':searchResult.status==='partial'?'Consulta parcial':searchResult.status==='failed'?'Falha na consulta':'A consultar as zonas…'}</span></div><div className="coverage-progress">{searchResult.tasks.map(task=><span key={task.province} className={cls(task.status==='succeeded'&&'complete',task.status==='failed'&&'failed')} title={task.error||`${task.count} resultados nesta fonte`}>{task.status==='succeeded'?<Check size={12}/>:<Clock3 size={12}/>} {task.province}<b>{task.count}</b></span>)}</div>{searchResult.results.length?<div className="business-grid">{searchResult.results.map(b=><BusinessCard key={b.id} business={b} busy={busy} onView={()=>run(()=>loadBusiness(b.id))} onSave={()=>saveBusiness(b)}/>)}</div>:<section className="panel"><Empty icon={<Search size={30}/>} title={searchResult.status==='failed'?'Não foi possível consultar a fonte.':'Não encontrámos resultados nesta consulta.'} description={searchResult.tasks.find(t=>t.error)?.error||'Experimente outro nicho ou cidade. A ausência de resultados nesta fonte não significa que não existam empresas na zona.'}><button className="button outline" onClick={()=>doSearch()}>Tentar novamente</button></Empty></section>}<div className="pagination"><span>{searchResult.total} resultados nesta fonte · Não é um inventário completo</span><div><IconButton label="Página anterior" onClick={()=>searchResult.page>1&&doSearch(searchResult.page-1)}><ChevronLeft size={18}/></IconButton><b>{searchResult.page}</b><IconButton label="Página seguinte" onClick={()=>searchResult.page<searchResult.pages&&doSearch(searchResult.page+1)}><ChevronRight size={18}/></IconButton></div></div></>:<><div className="results-heading"><h2>Oportunidades começam com uma pergunta.</h2></div><div className="search-start"><div className="search-start-copy"><span className="soft-icon"><Radar size={28}/></span><h2>Onde pode o seu<br/>trabalho fazer diferença?</h2><p>Pesquise por nicho e cidade em Moçambique. Receba contexto para começar uma conversa relevante.</p><div className="quick-searches">{[['Clínicas odontológicas','Maputo, Matola'],['Restaurantes','Beira'],['Salões de beleza','Nampula'],['Oficinas e mecânica','Tete']].map(([n,c])=><button key={n+c} onClick={()=>setFilters({...filters,niche:n,cities:c})}><MapPin size={13}/>{n} — {c}<ArrowUpRight size={13}/></button>)}</div></div><div className="country-outline"><MozambiqueMap/><span><span className="live-dot"/> TODO MOÇAMBIQUE</span></div></div></>}
 <div className="integrity-note"><ShieldCheck size={18}/><p><b>Informação para conversar, não para presumir.</b> A disponibilidade varia por fonte. Confirme sempre as necessidades com a empresa.</p></div></>}
 {user.profile.onboarded&&['business','outreach'].includes(view)&&business&&<><button className="back-link" onClick={()=>navigate('search')}><ChevronLeft size={16}/> Voltar à pesquisa</button><div className="company-heading"><div className="company-heading-left"><span className="business-icon large"><Building2 size={32}/></span><div><div className="eyebrow">{business.category} {business.isDemo&&<Pill tone="amber">Empresa fictícia</Pill>}</div><h1>{business.name}</h1><p><MapPin size={15}/>{business.locality}, {business.province}</p></div></div><button className="button outline" disabled={busy||business.saved} onClick={()=>saveBusiness(business)}>{business.saved?<Check size={17}/>:<Bookmark size={17}/>} {business.saved?'Guardada':'Guardar oportunidade'}</button></div><div className="tab-bar"><button className={view==='business'?'active':''} onClick={()=>navigate('business',business)}><FileText size={16}/> Empresa e oportunidades</button><button className={view==='outreach'?'active':''} onClick={()=>navigate('outreach',business)}><MessageCircle size={16}/> Preparar abordagem</button></div>
 {business.suppressed&&<div className="alert danger"><ShieldCheck size={18}/> Este contacto está marcado para não contactar. A geração e a abordagem estão bloqueadas.</div>}
 {view==='business'?<div className="detail-grid"><div><section className="panel"><div className="panel-heading"><div><h2>Primeiro, os factos.</h2><p>O que a fonte consultada permite observar.</p></div><ShieldCheck size={21}/></div><div className="evidence-list">{business.evidence.map(e=><article key={e.id}><span className="evidence-check"><Check size={14}/></span><div><span className="micro-label">{e.field==='name'?'EMPRESA':e.field==='location'?'LOCALIZAÇÃO':'ACTIVIDADE'}</span><h3>{e.value}</h3><p>{e.source} · {date(e.observedAt)}</p></div></article>)}</div><div className="panel-footer"><span><Database size={14}/> {business.source}</span><span>Consultado a {date(business.observedAt)}</span></div></section><section className="panel opportunity-panel"><div className="panel-heading"><div><h2><Sparkles size={19}/> Possibilidades para explorar</h2><p>Hipóteses de trabalho. A confirmação vem da conversa.</p></div></div>{analysis?<div className="opportunities-content"><Pill>{analysis.mode==='demo'?'Análise simulada':'Análise por IA'}</Pill><h2>{analysis.recommendedService}</h2><p>{analysis.reason}</p>{analysis.hypotheses.map((h,i)=><div className="hypothesis" key={i}><span>{String(i+1).padStart(2,'0')}</span><p>{h}</p></div>)}<div className="alert"><ShieldCheck size={17}/><span>{analysis.confidence}</span></div>{analysis.missingData.length>0&&<div><h4>O que ainda precisamos de saber</h4><ul className="missing-list">{analysis.missingData.map(m=><li key={m}>{m}</li>)}</ul></div>}<button className="button" onClick={()=>navigate('outreach',business)}>Preparar a conversa <ArrowRight size={17}/></button></div>:<Empty icon={<Sparkles size={28}/>} title="Uma análise com o seu serviço em mente." description="Relacione os dados disponíveis com o que oferece. Inclui uma primeira mensagem editável; custa 1 crédito."><button className="button" disabled={busy||business.suppressed} onClick={()=>generate()}>{busy?<LoaderCircle className="spin" size={17}/>:<Sparkles size={17}/>} Analisar oportunidade · 1 crédito</button></Empty>}</section></div><aside className="detail-aside"><section className="panel content"><h3>Dados de contacto</h3><div className="contact-line"><Mail size={17}/><div><span>Telefone</span><b>{business.phone||'Não disponível nesta fonte'}</b></div></div><p className="micro">Um telefone listado não confirma uma conta WhatsApp.</p><div className="contact-line"><Globe2 size={17}/><div><span>Website</span>{business.website?<a href={business.website} target="_blank" rel="noreferrer">{business.website.replace('https://','')} <ExternalLink size={12}/></a>:<b>Não identificado nesta fonte</b>}</div></div>{business.instagram&&<div className="contact-line"><Sparkles size={17}/><div><span>Instagram</span><b>{business.instagram}</b></div></div>}<div className="alert"><ShieldCheck size={17}/><span>A ausência de informação não prova ausência de presença digital.</span></div></section><section className="blue-note"><span className="soft-icon"><MessageCircle size={20}/></span><h3>Uma boa abordagem começa por ouvir.</h3><p>Apresente-se, faça uma pergunta e confirme se o seu serviço faz sentido.</p></section><section className="panel content"><h4>Qualidade da informação</h4><button className="text-button" onClick={()=>{const note=window.prompt('Que informação deve ser corrigida?');if(note)run(async()=>{await post('corrections',{businessId:business.id,note});notify('Pedido de correcção registado.');});}}>Sinalizar informação incorrecta <ArrowUpRight size={14}/></button><button className="text-button danger-text" disabled={business.suppressed} onClick={()=>{const reason=window.prompt('Motivo para não contactar esta empresa:');if(reason)run(async()=>{await post('suppressions',{businessId:business.id,reason});setBusiness({...business,suppressed:true});notify('Contacto bloqueado para futuras abordagens.');});}}>Marcar para não contactar</button></section></aside></div>:<div className="outreach-grid"><section className="panel content"><div className="step-label"><span>1</span><div><h2>A sua voz, o seu serviço.</h2><p>Prepare o contexto da abordagem.</p></div></div><div className="two-fields"><label>Tom da mensagem<select value={tone} onChange={e=>setTone(e.target.value)}>{['Profissional','Amigável','Consultivo'].map(t=><option key={t}>{t}</option>)}</select></label><label>Serviço em destaque<select value={service} onChange={e=>setService(e.target.value)}>{SERVICES.map(s=><option key={s}>{s}</option>)}</select></label></div><div className="editor-heading"><div className="step-label"><span>2</span><div><h2>Prepare uma boa conversa.</h2><p>{analysis?'Reveja, personalize e guarde a mensagem.':'Uma nova análise inclui a primeira mensagem.'}</p></div></div><button className="button outline compact" disabled={busy||business.suppressed} onClick={()=>generate(!!analysis)}>{busy?<LoaderCircle className="spin" size={15}/>:<Sparkles size={15}/>} {analysis?'Nova análise':'Gerar mensagem'} · 1 crédito</button></div><label className="sr-only" htmlFor="draft">Mensagem de abordagem</label><textarea id="draft" className="message-editor" value={draft} onChange={e=>setDraft(e.target.value)} placeholder="A sua mensagem aparece aqui após a análise. Também pode preparar um texto manualmente."/><div className="editor-meta"><span>{draft.length} caracteres</span><span>{analysis?.mode==='demo'?'Texto simulado · edite à sua medida':'Envio decidido por si'}</span></div><div className="outreach-actions"><button className="button outline" disabled={!draft||busy||business.suppressed} onClick={copyDraft}><Copy size={16}/> Copiar mensagem</button><button className="button" disabled={!analysis||!draft||busy||business.suppressed} onClick={saveDraft}><Check size={16}/> Guardar edição</button></div>{business.phone&&!business.suppressed?<a className="button whatsapp full" href={`https://wa.me/${business.phone.replace(/\D/g,'')}?text=${encodeURIComponent(draft)}`} target="_blank" rel="noreferrer"><MessageCircle size={18}/> Abrir WhatsApp <ExternalLink size={15}/></a>:<div className="alert"><MessageCircle size={18}/><span>{business.suppressed?'A abordagem está bloqueada por pedido de não contacto.':'Sem telefone disponível. Prepare o texto e confirme outro canal de contacto com a empresa.'}</span></div>}<p className="micro">Abrir WhatsApp não confirma envio, entrega ou leitura da mensagem. Registe o contacto apenas depois de o realizar.</p>{selectedLead&&<button className="text-button" disabled={busy} onClick={()=>run(async()=>{await api('leads/'+selectedLead.id,{method:'PATCH',body:JSON.stringify({stage:'Contactado'})});notify('Contacto confirmado por si. Etapa actualizada.');})}><CheckCheck size={16}/> Já realizei o contacto · Marcar como Contactado</button>}</section><aside className="message-preview"><div className="preview-title"><span>PRÉ-VISUALIZAÇÃO</span><Pill>Rascunho</Pill></div><div className="phone-frame"><div className="phone-contact"><span className="business-icon"><Building2 size={20}/></span><div><b>{business.name}</b><small>Pré-visualização da mensagem</small></div></div><div className="phone-body"><span className="phone-day">RASCUNHO · NÃO ENVIADO</span><div className="message-bubble">{draft||'A sua próxima conversa começa com uma mensagem relevante.'}<small>Pré-visualização</small></div></div><div className="phone-bottom"><span>A mensagem será enviada por si</span><Send size={17}/></div></div><div className="preview-tip"><ShieldCheck size={20}/><p>Não presuma as necessidades. Uma pergunta honesta abre mais espaço para conversar.</p></div></aside></div>}
 {job&&['queued','running'].includes(job.status)&&<div className="job-bar"><LoaderCircle className="spin" size={18}/><span>Análise em curso. O crédito está reservado.</span><button onClick={()=>run(async()=>{const j=await post<Job>('jobs/'+job.id+'/cancel');setJob(j);await refreshUser();})}>Cancelar tarefa</button></div>}</>}
 {user.profile.onboarded&&view==='leads'&&<><div className="page-heading"><div><div className="eyebrow"><Bookmark size={14}/> RELAÇÕES QUE AVANÇAM</div><h1>Cada conversa, no seu lugar.</h1><p>Acompanhe oportunidades e não perca o próximo passo.</p></div><button className="button" onClick={()=>navigate('search')}><Plus size={17}/> Encontrar empresas</button></div><div className="stage-filters"><button className={!stageFilter?'active':''} onClick={()=>setStageFilter('')}>Todas <b>{leads.length}</b></button>{STAGES.map((s,i)=><button key={s} className={stageFilter===s?'active':''} onClick={()=>setStageFilter(s)}><span className={'stage-dot stage-'+i}/>{s}<b>{leads.filter(l=>l.stage===s).length}</b></button>)}</div><section className="panel"><div className="panel-heading"><h2>As suas oportunidades</h2><div className="inline-search"><Search size={16}/><input aria-label="Procurar oportunidades" placeholder="Procurar empresa…" value={leadSearch} onChange={e=>setLeadSearch(e.target.value)}/></div></div>{leads.filter(l=>(!stageFilter||l.stage===stageFilter)&&l.business.name.toLowerCase().includes(leadSearch.toLowerCase())).length?<div className="lead-list">{leads.filter(l=>(!stageFilter||l.stage===stageFilter)&&l.business.name.toLowerCase().includes(leadSearch.toLowerCase())).map(l=><button className="lead-row" key={l.id} onClick={()=>openLead(l)}><span className="business-icon"><Building2 size={21}/></span><div className="lead-name"><b>{l.business.name}</b><small>{l.business.locality} · {l.business.province}</small></div><Pill tone={'stage-tone-'+STAGES.indexOf(l.stage)}>{l.stage}</Pill><span className="lead-followup">{l.nextAction||'Definir próximo passo'}<small>{l.nextActionAt?date(l.nextActionAt):'Sem data agendada'}</small></span><strong className="lead-amount">{l.amountMinor!==null?money(l.amountMinor):'—'}</strong><ChevronRight size={17}/></button>)}</div>:<Empty title={leads.length?'Nenhuma oportunidade neste filtro.':'A próxima relação começa aqui.'} description="Guarde empresas da pesquisa para acompanhar contactos, propostas e próximos passos."><button className="button" onClick={()=>navigate('search')}>Encontrar empresas <ArrowRight size={16}/></button></Empty>}</section></>}
 {user.profile.onboarded&&view==='account'&&<><div className="page-heading"><div><div className="eyebrow"><Settings2 size={14}/> À SUA MEDIDA</div><h1>O seu espaço, as suas escolhas.</h1><p>Perfil comercial, utilização e controlo dos seus dados.</p></div></div><div className="detail-grid"><section className="panel content"><h2>Perfil comercial</h2><p className="muted">A base para mensagens mais relevantes.</p><ProfileForm user={user} profile={profile||user.profile} busy={busy} onSubmit={saveProfile}/></section><div><section className="account-credit"><Sparkles size={25}/><span>CRÉDITOS DISPONÍVEIS</span><strong>{user.credits.available}</strong><p>{user.credits.reserved} reservados · {user.credits.spent} utilizados</p><div><Check size={15}/> 1 análise com mensagem = 1 crédito</div><div><Check size={15}/> Editar e reabrir são gratuitos</div><p className="micro">Piloto gratuito. Sem renovação ou cobrança automática. Pagamentos locais previstos para a fase seguinte.</p></section><section className="panel content"><h3>Os seus dados estão sob o seu controlo.</h3><p className="muted">Exporte o seu trabalho ou peça a eliminação da conta.</p><div className="actions"><button className="button outline compact" onClick={()=>requestPrivacy('export')} disabled={busy}><Download size={15}/> Exportar dados</button><button className="text-button danger-text" onClick={()=>requestPrivacy('delete')} disabled={busy}>Pedir eliminação</button></div>{requests.map(r=><div className="privacy-row" key={r.id}><span>{r.type==='export'?'Exportação':'Eliminação'} · {r.status==='ready'?'Pronta':r.status==='pending'?'Pendente':r.status}</span>{r.type==='export'&&<a href={'/api/privacy/'+r.id+'/export'} download>Descarregar <Download size={13}/></a>}</div>)}</section></div></div><section className="panel"><div className="panel-heading"><h2>Histórico de utilização</h2><Wallet size={19}/></div><div className="ledger">{usage.map(e=><div key={e.id}><span className={cls('ledger-icon',e.kind==='grant'&&'positive')}>{e.kind==='grant'?<Plus size={17}/>:<ArrowDownLeft size={17}/>}</span><span><b>{e.description}</b><small>{date(e.createdAt)}</small></span><strong>{e.kind==='grant'?'+':e.kind==='consume'?'-':''}{e.units} <small>crédito{e.units!==1?'s':''}</small></strong></div>)}</div></section>{mode==='demo'&&outbox.length>0&&<section className="panel content"><h3>Caixa de mensagens local</h3><p className="muted">Mensagens de teste, sem envio por e-mail.</p>{outbox.map(m=><a className="outbox-link" key={m.id} href={m.link}>{m.kind==='confirm'?'Confirmar e-mail':'Recuperar acesso'} <ArrowUpRight size={15}/></a>)}</section>}</>}
 {user.profile.onboarded&&view==='admin'&&user.role==='admin'&&<><div className="page-heading"><div><div className="eyebrow"><ShieldCheck size={14}/> ADMINISTRAÇÃO DO PILOTO</div><h1>Qualidade antes de quantidade.</h1><p>Importações autorizadas, operações e pedidos de dados.</p></div><Pill tone="amber">Administrador</Pill></div><div className="detail-grid"><section className="panel content"><h2>Importar empresas por CSV</h2><p className="muted">Até 500 linhas. Colunas: name, category, province, locality, sourceId, phone, website, countryCode.</p><form onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);run(async()=>{const r=await post<{imported:number}>('admin/import',{csv:form.get('csv'),source:form.get('source'),authorized:form.get('authorized')==='on'});notify(`${r.imported} empresas importadas.`);});}}><label>Origem dos dados<input name="source" required minLength={3} placeholder="Nome da fonte autorizada"/></label><label>Conteúdo CSV<textarea name="csv" rows={7} required placeholder={'name,category,province,locality,sourceId,phone,website,countryCode\nEmpresa Exemplo,Restauração,Sofala,Beira,ref-01,,,MZ'}/></label><label className="checkbox"><input name="authorized" type="checkbox" required/> Confirmo ter autorização de uso e armazenamento destes dados.</label><button className="button" disabled={busy}><Database size={16}/> Validar e importar</button></form></section><section className="panel content"><h2>Atribuir créditos do piloto</h2><form onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);run(async()=>{await post('admin/grant',{workspaceId:form.get('workspaceId'),units:Number(form.get('units')),reason:form.get('reason')});await refreshUser();notify('Créditos atribuídos e registados.');});}}><label>Espaço de trabalho<select name="workspaceId">{admin?.workspaces.map(w=><option key={w.id} value={w.id}>{w.name} · {w.email}</option>)}</select></label><label>Quantidade<input name="units" type="number" min={1} max={10000} defaultValue={10} required/></label><label>Motivo<input name="reason" required minLength={3} placeholder="Ex.: extensão do piloto"/></label><button className="button outline" disabled={busy}><Plus size={16}/> Atribuir créditos</button></form></section></div><section className="panel content"><h2>Tarefas de análise</h2>{admin?.jobs.length?<div className="admin-rows">{admin.jobs.map(j=><div key={j.id}><code>{j.id.slice(0,8)}</code><Pill tone={j.status==='failed'?'red':'blue'}>{j.status}</Pill><span>{j.attempts} tentativa(s)</span><small>{j.error||'—'}</small></div>)}</div>:<p className="muted">Nenhuma tarefa de análise criada.</p>}<p className="micro">Após falha definitiva, a reserva é libertada. Uma nova análise deve ser iniciada na ficha da empresa, com custo informado.</p></section><section className="panel content"><h2>Pedidos de privacidade</h2>{admin?.requests.length?admin.requests.map(r=><div className="privacy-row" key={r.id}><span>{r.type} · {r.status} · {r.id.slice(0,8)}</span><button className="button outline compact" disabled={busy} onClick={()=>{if(window.confirm(r.type==='delete'?'Eliminar definitivamente os dados privados deste utilizador?':'Concluir este pedido?'))run(async()=>{await post('admin/privacy/'+r.id+'/complete');const remaining=await refreshUser();if(remaining)setAdmin(await api<AdminData>('admin'));notify('Pedido processado.');});}}>Processar pedido</button></div>):<p className="muted">Sem pedidos registados.</p>}</section><section className="panel content"><h2>Correcções de informação</h2>{admin?.corrections.length?admin.corrections.map(c=><div className="privacy-row" key={c.id}><span>{c.note} · {c.status}</span>{c.status==='pending'&&<button className="button outline compact" onClick={()=>run(async()=>{await post('admin/corrections/'+c.id+'/complete');setAdmin(await api<AdminData>('admin'));notify('Correcção marcada como revista.');})}>Marcar como revista</button>}</div>):<p className="muted">Sem correcções pendentes.</p>}</section></>}
 <footer className="workspace-footer"><span><Radar size={14}/> Prospecta · O próximo passo é seu.</span><span>Feito para Moçambique <span className="country-dot"/></span></footer></main></div>
 {view==='leads'&&selectedLead&&<div className="modal-backdrop drawer-backdrop" onClick={()=>setSelectedLead(null)}><section role="dialog" aria-modal="true" aria-labelledby="lead-title" className="lead-drawer" onClick={e=>e.stopPropagation()}><div className="row"><Pill>OPORTUNIDADE</Pill><IconButton label="Fechar oportunidade" onClick={()=>setSelectedLead(null)}><X size={20}/></IconButton></div><h2 id="lead-title">{selectedLead.business.name}</h2><p className="muted">{selectedLead.business.locality} · {selectedLead.business.province}</p><form onSubmit={updateLead}><label>Etapa<select name="stage" defaultValue={selectedLead.stage}>{STAGES.map(s=><option key={s}>{s}</option>)}</select></label><label>Próximo passo<input name="nextAction" defaultValue={selectedLead.nextAction} placeholder="Ex.: apresentar uma demonstração"/></label><div className="two-fields"><label>Data de seguimento<input name="due" type="date" defaultValue={selectedLead.nextActionAt?.slice(0,10)||''}/></label><label>Valor proposto (MT)<input name="amount" type="number" min={0} step="0.01" defaultValue={selectedLead.amountMinor!==null?selectedLead.amountMinor/100:''}/></label></div><label>Notas<textarea name="note" rows={4} defaultValue={selectedLead.note} placeholder="O que é importante para esta conversa?"/></label><button className="button full" disabled={busy}><Check size={16}/> Guardar alterações</button></form><button className="button outline full" onClick={()=>run(async()=>{await loadBusiness(selectedLead.businessId);})}>Ver ficha da empresa <ArrowRight size={16}/></button><h3>Histórico</h3><div className="activity-list">{selectedLead.activities.map(a=><div key={a.id}><span className="activity-dot"/><div><p>{a.note}</p><small>{date(a.createdAt)}</small></div></div>)}</div></section></div>}
 </div>;
}

function ProfileForm({user,profile,busy,onSubmit}:{user:User;profile:Profile;busy:boolean;onSubmit:(event:FormEvent<HTMLFormElement>)=>void}){return <form onSubmit={onSubmit} className="profile-form" key={user.id}><div className="two-fields"><label>O seu nome<input name="name" defaultValue={user.name} required minLength={2}/></label><label>Serviço principal<select name="service" defaultValue={profile.service}>{SERVICES.map(s=><option key={s}>{s}</option>)}</select></label></div><label>Como apresenta o seu trabalho?<textarea name="pitch" defaultValue={profile.pitch} maxLength={1000} rows={3} placeholder="Ajudo pequenos negócios a…"/></label><div className="two-fields"><label>Localização de base<select name="province" defaultValue={profile.province}><option value="">Seleccionar província</option>{PROVINCES.map(p=><option key={p}>{p}</option>)}</select></label><label>Contacto profissional (opcional)<input name="phone" type="tel" defaultValue={profile.phone} placeholder="+258 …"/></label></div><label className="checkbox"><input name="nationwide" type="checkbox" defaultChecked={profile.nationwide}/> Presto serviços em todo Moçambique.</label><p className="micro">A sua localização não limita as zonas onde pode pesquisar empresas.</p><button className="button" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>}Guardar perfil</button></form>;}
function formatPhone(p: string | null) {
  if (!p) return null;
  const digits = p.replace(/\D/g, '');
  if (digits.startsWith('258') && digits.length >= 11) {
    return `+258 ${digits.slice(3, 5)} ${digits.slice(5, 8)} ${digits.slice(8)}`;
  }
  return p;
}
function BusinessCard({business:b,busy,onView,onSave}:{business:Business;busy:boolean;onView:()=>void;onSave:()=>void}){return <article className="business-card"><div className="row"><span className="business-icon"><Building2 size={23}/></span><div className="card-tags"><Pill tone={b.isDemo?"amber":"blue"}>{b.isDemo?"Fictícia":"Fonte autorizada"}</Pill><IconButton label={b.saved?'Empresa guardada':'Guardar '+b.name} onClick={onSave}>{b.saved?<Bookmark fill="currentColor" size={18}/>:<Bookmark size={18}/>}</IconButton></div></div><span className="business-category">{b.category}</span><h3><button onClick={onView}>{b.name}</button></h3><p className="location"><MapPin size={14}/>{b.locality}, {b.province}</p><div className="business-facts"><span className={cls('fact-pill',b.phone?'fact-phone':'fact-phone-none')}><Phone size={13}/>{b.phone?<b>{formatPhone(b.phone)}</b>:'Sem telefone'}</span><span className={cls('fact-pill',b.website?'fact-web':'fact-web-none')}><Globe2 size={13}/>{b.website?'Com website':'Sem website'}</span>{b.instagram&&<span className="fact-pill fact-ig"><Sparkles size={13}/><b>{b.instagram}</b></span>}</div><div className="business-source"><Database size={13}/><span>{b.source}<small>Actualizado a {date(b.observedAt)}</small></span></div><button className="card-action" onClick={onView} disabled={busy}>Ver empresa e possibilidades <ArrowUpRight size={17}/></button></article>;}
function MozambiqueMap(){return <svg viewBox="0 0 200 280" aria-label="Ilustração esquemática de Moçambique" role="img"><defs><linearGradient id="map-fill" x1="0" x2="1" y1="0" y2="1"><stop stopColor="#e1edff"/><stop offset="1" stopColor="#a7c8f7"/></linearGradient></defs><path d="M76 22 116 28 155 12 171 41 154 66 161 91 145 118 127 137 124 158 111 183 95 194 94 218 82 240 64 265 48 257 58 237 55 218 68 194 64 172 76 153 68 131 80 111 77 92 58 73 44 74 37 57 61 50Z" fill="url(#map-fill)" stroke="#7daae7" strokeWidth="1.5"/><path d="m57 74 44 18 31-2m-56 41 66-13m-75 36 54 4m-57 36 32 1m-39 43 31-20m15-189-12 63" stroke="#fff" strokeWidth="1.5" fill="none"/>{[[128,57],[99,124],[78,177],[69,231]].map(([x,y],i)=><g key={i}><circle cx={x} cy={y} r="11" fill="#1877f2" opacity=".12"/><circle cx={x} cy={y} r="4" fill="#1877f2" stroke="white" strokeWidth="2"/></g>)}</svg>;}
